package org.transittr;
import android.content.Context;import java.io.*;import java.util.*;import java.util.zip.*;
/** One bounded archive avoids the per-file 4 KiB cost of hundreds of small schedules. */
public final class ScheduleCache {
 public static final int LIMIT=65536;
 private static File file(Context c){return new File(c.getFilesDir(),"ego-times-cache.zip");}
 private static byte[] read(InputStream in,int limit)throws IOException{try{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("Saat önbelleği sınırı");out.write(b,0,n);}return out.toByteArray();}finally{in.close();}}
 private static byte[] gzip(byte[] raw)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();GZIPOutputStream zip=new GZIPOutputStream(out);zip.write(raw);zip.close();return out.toByteArray();}
 private static LinkedHashMap<String,byte[]> load(Context c)throws IOException{LinkedHashMap<String,byte[]> values=new LinkedHashMap<String,byte[]>();File f=file(c);if(!f.exists())return values;if(f.length()>LIMIT)return values;ZipFile zip=new ZipFile(f);try{Enumeration<? extends ZipEntry> all=zip.entries();int total=0;while(all.hasMoreElements()&&values.size()<800){ZipEntry e=all.nextElement();if(!e.getName().matches("[A-Za-z0-9-]{1,16}\\.gz"))continue;byte[] bytes=read(zip.getInputStream(e),65536);total+=bytes.length;if(total>LIMIT)throw new IOException("Saat arşivi sınırı");values.put(e.getName(),bytes);}}finally{zip.close();}return values;}
 private static byte[] archive(LinkedHashMap<String,byte[]> values)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();ZipOutputStream zip=new ZipOutputStream(out);for(Map.Entry<String,byte[]> e:values.entrySet()){byte[] bytes=e.getValue();CRC32 crc=new CRC32();crc.update(bytes);ZipEntry entry=new ZipEntry(e.getKey());entry.setMethod(ZipEntry.STORED);entry.setSize(bytes.length);entry.setCompressedSize(bytes.length);entry.setCrc(crc.getValue());zip.putNextEntry(entry);zip.write(bytes);zip.closeEntry();}zip.close();return out.toByteArray();}
 private static void save(Context c,LinkedHashMap<String,byte[]> values)throws IOException{byte[] bytes=archive(values);while(bytes.length>LIMIT&&values.size()>1){values.remove(values.keySet().iterator().next());bytes=archive(values);}if(bytes.length>LIMIT)throw new IOException("Saat arşivi sınırı");File target=file(c),tmp=new File(target+".tmp");target.getParentFile().mkdirs();FileOutputStream out=new FileOutputStream(tmp);try{out.write(bytes);}finally{out.close();}if(!tmp.renameTo(target)){tmp.delete();throw new IOException("Saat arşivi kaydedilemedi");}}
 public static synchronized InputStream open(Context c,String code)throws IOException{File f=file(c);if(!f.exists())return null;ZipFile zip=new ZipFile(f);byte[] bytes;try{ZipEntry entry=zip.getEntry(code+".gz");if(entry==null)return null;bytes=read(zip.getInputStream(entry),65536);}finally{zip.close();}return new ByteArrayInputStream(read(new GZIPInputStream(new ByteArrayInputStream(bytes),8192),262144));}
 public static synchronized void write(Context c,String code,byte[] raw)throws IOException{LinkedHashMap<String,byte[]> values;try{values=load(c);}catch(IOException e){values=new LinkedHashMap<String,byte[]>();}values.remove(code+".gz");values.put(code+".gz",gzip(raw));save(c,values);}
 public static synchronized void migrate(Context c)throws IOException{new File(file(c)+".tmp").delete();if(file(c).exists()&&file(c).length()>LIMIT)file(c).delete();File directory=new File(c.getFilesDir(),"ego-times");File[] old=directory.listFiles();if(old==null)return;LinkedHashMap<String,byte[]> values;try{values=load(c);}catch(IOException e){values=new LinkedHashMap<String,byte[]>();}boolean changed=false;for(File f:old)if(f.getName().matches("[A-Za-z0-9-]{1,16}\\.json")){String key=f.getName().substring(0,f.getName().length()-5)+".gz";if(!values.containsKey(key)){byte[] bytes=read(new FileInputStream(f),262144);values.put(key,bytes.length>2&&(bytes[0]&255)==31?bytes:gzip(bytes));changed=true;}}if(changed)save(c,values);for(File f:old)if(f.getName().matches("[A-Za-z0-9-]{1,16}\\.(json|tmp)"))f.delete();directory.delete();}
}
